// Disposable PG model only. No real credentials, external network, RPC, Storage, or grants.
import {generateKeyPairSync,sign,verify,randomUUID,createHash} from 'node:crypto';
const e=x=>Buffer.from(JSON.stringify(x)).toString('base64url');const dec=x=>JSON.parse(Buffer.from(x,'base64url'));
const check=(v,m='denied')=>{if(!v)throw Error(m)};const uuid=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(x);const actions=['plan_erasure','cleanup_orphan','authorize'];
export function atomicModel(pool,{now=()=>Math.floor(Date.now()/1000)}={}){
 const key=generateKeyPairSync('ed25519'),identity=generateKeyPairSync('ed25519');
 const pack=(k,v)=>{let x=e({alg:'EdDSA',typ:'JWT'})+'.'+e(v);return x+'.'+sign(null,Buffer.from(x),k).toString('base64url')};
 const unpack=(k,v)=>{try{let a=v.split('.');check(a.length===3);let h=dec(a[0]);check(h.alg==='EdDSA'&&h.typ==='JWT');check(verify(null,Buffer.from(a[0]+'.'+a[1]),k,Buffer.from(a[2],'base64url')));return dec(a[1])}catch{throw Error('invalid token')}};
 async function transaction(fn){let c=await pool.connect();try{await c.query('BEGIN');let r=await fn(c);await c.query('COMMIT');return r}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}
 async function locked(c,id){let r=await c.query('SELECT * FROM synthetic_operator.subjects WHERE id=$1 FOR UPDATE',[id]);check(r.rowCount===1&&r.rows[0].active,'inactive or missing subject');return r.rows[0]}
 async function register(id,person,admin=false){return transaction(async c=>{let r=await c.query('SELECT * FROM synthetic_operator.subjects WHERE id=$1 FOR UPDATE',[id]);if(r.rowCount){check(r.rows[0].identity_id===person,'identity mismatch');await c.query('UPDATE synthetic_operator.subjects SET epoch=epoch+1,active=true WHERE id=$1',[id])}else await c.query('INSERT INTO synthetic_operator.subjects(id,identity_id,is_admin) VALUES($1,$2,$3)',[id,person,admin]);});}
 async function bump(id,mode){check(['disable','mfa_change','revoke_all'].includes(mode));return transaction(async c=>{await locked(c,id);await c.query('UPDATE synthetic_operator.subjects SET epoch=epoch+1,active=CASE WHEN $2=\'disable\' THEN false ELSE active END WHERE id=$1',[id,mode]);});}
 async function assertion(sub,caseId,opts={}){const t=now();let q=await pool.query('SELECT epoch FROM synthetic_operator.subjects WHERE id=$1 AND active',[sub]);check(q.rowCount===1,'subject');return pack(identity.privateKey,{iss:'synthetic-idp',aud:'review',sub,case_id:caseId,epoch:Number(q.rows[0].epoch),aal:opts.mfa===false?'aal1':'aal2',mfa_at:t-(opts.age??0),iat:t,exp:t+(opts.lifetime??60),jti:randomUUID()})}
 async function issue(sub,aud,target,nonce,opts={}){check(actions.includes(aud),'action');check(uuid(sub)&&uuid(target)&&uuid(nonce),'invalid uuid');let q=await pool.query('SELECT epoch FROM synthetic_operator.subjects WHERE id=$1 AND active',[sub]);check(q.rowCount===1,'subject');let t=now();return pack(key.privateKey,{iss:opts.issuer??'synthetic-issuer',sub,jti:randomUUID(),aud,target,nonce,epoch:Number(q.rows[0].epoch),iat:t,exp:t+(opts.lifetime??60)});}
 function claim(token,call){check(uuid(call.sub)&&uuid(call.target)&&uuid(call.nonce),'invalid uuid');let p=unpack(key.publicKey,token),t=now();check(p.iss==='synthetic-issuer'&&p.sub===call.sub&&p.aud===call.action&&actions.includes(p.aud)&&p.target===call.target&&p.nonce===call.nonce&&p.jti&&Number.isInteger(p.epoch),'claims');check(Number.isInteger(p.iat)&&p.iat<=t&&Number.isInteger(p.exp)&&p.exp>t&&p.exp-p.iat<=60,'expiry');return p}
 async function denied(err){const allowed=['claims','expiry','epoch','revoked','inactive or missing subject','consumed','invalid uuid','invalid token','reviewer MFA','review epoch','case','reviewer denied','same identity','assertion replay'];let reason=allowed.includes(err.message)?err.message:'other';try{await pool.query("INSERT INTO synthetic_operator.audit(event,recorded_at) VALUES($1,$2) ON CONFLICT (event,recorded_at) WHERE event LIKE 'denied:%' DO UPDATE SET occurrences=synthetic_operator.audit.occurrences+1",['denied:'+reason,Math.floor(now()/60)*60]);}catch(auditError){err.auditFailure=true;}}
 async function consume(token,call,{fail=false,loseReply=false}={}){let p;try{p=claim(token,call)}catch(err){await denied(err);throw err}let result;try{result=await transaction(async c=>{let sub=await locked(c,p.sub);check(Number(sub.epoch)===p.epoch,'epoch');let rev=await c.query('SELECT 1 FROM synthetic_operator.revoked WHERE jti=$1',[p.jti]);check(!rev.rowCount,'revoked');let r=await c.query('INSERT INTO synthetic_operator.consumptions(jti,subject_id,action,target,outcome) VALUES($1,$2,$3,$4,$5) ON CONFLICT DO NOTHING RETURNING jti',[p.jti,p.sub,p.aud,p.target,'done']);check(r.rowCount===1,'consumed');await c.query('SAVEPOINT synthetic_action');let outcome='done';try{await c.query('INSERT INTO synthetic_operator.actions(jti,action,target) VALUES($1,$2,$3)',[p.jti,p.aud,p.target]);if(fail)await c.query('SELECT 1/0');await c.query('RELEASE SAVEPOINT synthetic_action')}catch(error){await c.query('ROLLBACK TO SAVEPOINT synthetic_action');outcome='rejected';await c.query('UPDATE synthetic_operator.consumptions SET outcome=$2 WHERE jti=$1',[p.jti,outcome]);}await c.query('INSERT INTO synthetic_operator.audit(event,jti,subject_id,recorded_at) VALUES($1,$2,$3,$4)',[outcome,p.jti,p.sub,now()]);return {outcome,grantsAccess:false};});}catch(err){await denied(err);throw err}if(loseReply)throw Error('synthetic lost commit reply');return result;}
 async function status(token,call){let p=claim(token,call);return transaction(async c=>{let s=await locked(c,p.sub);check(Number(s.epoch)===p.epoch,'epoch');check(!(await c.query('SELECT 1 FROM synthetic_operator.revoked WHERE jti=$1',[p.jti])).rowCount,'revoked');let r=await c.query('SELECT outcome FROM synthetic_operator.consumptions WHERE jti=$1 AND subject_id=$2 AND action=$3 AND target=$4',[p.jti,p.sub,p.aud,p.target]);return {status:r.rowCount?r.rows[0].outcome:'pending_or_unknown',retryAllowed:false,grantsAccess:false};});}

 // Recovery capability is synthetic; a real service needs independent caller authentication.
 const hash=secret=>createHash('sha256').update(secret).digest('hex');
 async function reserve(token,call,secret){check(typeof secret==='string'&&secret.length>=32,'recovery secret');let p=claim(token,call);await transaction(async c=>{let sub=await locked(c,p.sub);check(Number(sub.epoch)===p.epoch,'epoch');check(!(await c.query('SELECT 1 FROM synthetic_operator.revoked WHERE jti=$1',[p.jti])).rowCount,'revoked');await c.query("INSERT INTO synthetic_operator.operation_ledger VALUES($1,$2,$3,$4,$5,'reserved') ON CONFLICT DO NOTHING",[p.jti,p.sub,p.aud,p.target,hash(secret)]);let row=await c.query('SELECT * FROM synthetic_operator.operation_ledger WHERE jti=$1 FOR UPDATE',[p.jti]);check(row.rows[0].subject_id===p.sub&&row.rows[0].action===p.aud&&row.rows[0].target===p.target&&row.rows[0].recovery_hash===hash(secret),'ledger binding');});return {jti:p.jti,grantsAccess:false};}
 async function recover(jti,secret){check(uuid(jti)&&typeof secret==='string','recovery denied');let r=await pool.query('SELECT state FROM synthetic_operator.operation_ledger WHERE jti=$1 AND recovery_hash=$2',[jti,hash(secret)]);check(r.rowCount===1,'recovery denied');return {status:r.rows[0].state==='done'?'done':'pending_or_unknown',retryAllowed:false,grantsAccess:false};}
 async function ledgerAct(token,call,secret,{loseReply=false}={}){let p=claim(token,call);let result=await transaction(async c=>{let sub=await locked(c,p.sub);check(Number(sub.epoch)===p.epoch,'epoch');check(!(await c.query('SELECT 1 FROM synthetic_operator.revoked WHERE jti=$1',[p.jti])).rowCount,'revoked');let r=await c.query('SELECT * FROM synthetic_operator.operation_ledger WHERE jti=$1 FOR UPDATE',[p.jti]);check(r.rowCount===1&&r.rows[0].recovery_hash===hash(secret)&&r.rows[0].subject_id===p.sub&&r.rows[0].action===p.aud&&r.rows[0].target===p.target,'ledger binding');if(r.rows[0].state==='done')return {status:'done',grantsAccess:false};await c.query('INSERT INTO synthetic_operator.ledger_actions(jti) VALUES($1)',[p.jti]);await c.query("UPDATE synthetic_operator.operation_ledger SET state='done' WHERE jti=$1",[p.jti]);return {status:'done',grantsAccess:false};});if(loseReply)throw Error('synthetic lost commit reply');return result;}
 async function revoke(token,actor){let p=unpack(key.publicKey,token);return transaction(async c=>{let who=await locked(c,actor);check(actor===p.sub||who.is_admin,'revoke denied');await c.query('INSERT INTO synthetic_operator.revoked(jti,subject_id) VALUES($1,$2) ON CONFLICT DO NOTHING',[p.jti,p.sub]);});}
 async function openCase(id,sub,requester){check(sub!==requester,'subject requester');await pool.query('INSERT INTO synthetic_operator.support_cases(id,subject_id,requester) VALUES($1,$2,$3)',[id,sub,requester]);}
 async function approve(id,assertionToken){try{let p=unpack(identity.publicKey,assertionToken),t=now();check(p.iss==='synthetic-idp'&&p.aud==='review'&&p.case_id===id&&uuid(p.jti)&&p.aal==='aal2'&&Number.isInteger(p.mfa_at)&&p.mfa_at<=t&&t-p.mfa_at<=120&&p.iat<=t&&p.exp>t&&p.exp-p.iat<=60,'reviewer MFA');return transaction(async c=>{let reviewer=await locked(c,p.sub);check(Number.isInteger(p.epoch)&&Number(reviewer.epoch)===p.epoch,'review epoch');let item=await c.query('SELECT * FROM synthetic_operator.support_cases WHERE id=$1 FOR UPDATE',[id]);check(item.rowCount===1,'case');let x=item.rows[0];check(p.sub!==x.subject_id&&p.sub!==x.requester,'reviewer denied');let rs=await c.query('SELECT identity_id FROM synthetic_operator.subjects WHERE id=ANY($1::uuid[])',[ [x.subject_id,x.requester] ]);check(!rs.rows.some(q=>q.identity_id===reviewer.identity_id),'same identity');let used=await c.query('INSERT INTO synthetic_operator.used_assertions(jti,reviewer,case_id) VALUES($1,$2,$3) ON CONFLICT DO NOTHING RETURNING jti',[p.jti,p.sub,id]);check(used.rowCount===1,'assertion replay');await c.query('INSERT INTO synthetic_operator.reviews(case_id,reviewer,identity_id,mfa_at,epoch,reviewed_at) VALUES($1,$2,$3,$4,$5,$6)',[id,p.sub,reviewer.identity_id,p.mfa_at,p.epoch,t]);await c.query('INSERT INTO synthetic_operator.audit(event,reviewer,mfa_at,recorded_at) VALUES($1,$2,$3,$4)',['review',p.sub,p.mfa_at,t]);return {grantsAccess:false};});}catch(err){await denied(err);throw err}}
 async function completeCase(id){let n=await pool.query('SELECT count(*)::int n FROM synthetic_operator.reviews WHERE case_id=$1',[id]);check(n.rows[0].n>=2,'two reviewers');return {status:'reviewed-not-authorized',grantsAccess:false};}
 return {register,bump,assertion,issue,consume,status,reserve,recover,ledgerAct,revoke,openCase,approve,completeCase};
}
